/*
 * Build Automation Gateway request envelope for listDueNextActions.
 * - organizationId, connectionId, serviceId are bound server-side; body is a claim, never trusted alone.
 * - workflowId, workflowRevision, n8nExecutionId are computed inside the n8n host; we read them from $workflow and $execution.
 * - idempotencyKey is stable for the same wall-clock window so retries dedupe at the gateway.
 * - correlationId rides the whole flow; it is tracking only.
 * - triggerLabel: 'TICK_15M' | 'DAILY_DIGEST' selects the workflow revision branch.
 */
const slug = (s) => String(s || '').replace(/[^A-Za-z0-9._:-]/g, '').slice(0, 128);
const idemWindow = 'sla-' + (new Date()).toISOString().slice(0, 16).replace(/[-:T]/g, '');
const triggerLabel = ($env.N8N_TRIGGER_LABEL || 'TICK_15M');
const envelope = {
  schemaVersion: '1',
  commandId: ('cmd-' + idemWindow).slice(0, 64),
  commandName: 'listDueNextActions',
  idempotencyKey: idemWindow,
  correlationId: 'corr-' + idemWindow + '-' + Math.random().toString(36).slice(2, 10),
  organizationId: $env.HRP_AUTOMATION_ORG_ID,
  source: { kind: 'HRP_UI', provider: 'HRP_UI', connectionId: null },
  actor: { kind: 'SERVICE', serviceId: $env.HRP_AUTOMATION_SERVICE_ID },
  occurredAt: new Date().toISOString(),
  automationSource: {
    kind: 'N8N_AUTOMATION',
    workflowId: slug($workflow.id),
    workflowRevision: 2,
    n8nExecutionId: slug($execution.id),
    workflowLabel: 'sla-reminder-crm',
    sourceEventId: triggerLabel
  },
  operation: {
    op: 'listDueNextActions',
    payload: {
      schemaVersion: '1',
      statusFilter: 'OPEN_OR_DUE',
      pageSize: 200
    }
  }
};
const rawBody = JSON.stringify(envelope);
return [
  {
    json: {
      envelope: envelope,
      rawBody: rawBody,
      credentialId: 'CRM_AUTOMATION_HMAC',
      triggerLabel: triggerLabel
    }
  }
];

/*
 * Filter due-list response:
 *   - DROP status === 'CANCELLED' or 'DONE' (never notify finished items).
 *   - DROP snoozeMode === 'SNOOZED' (snooze affects ONLY notification, not SLA / canonical state).
 *     Items that are snoozed remain in the SLA bucket for the orchestrator, but this workflow
 *     does NOT send a notification for them. The 15-min tick and the daily digest must produce
 *     the SAME logical bucket for the SAME (item, day) so the dedupe key is stable.
 *   - BUCKET each surviving item into an slaBucket based on time-to-dueAt:
 *       DUE_SOON : 0 < dueAt - now <= 60 minutes
 *       DUE      :  dueAt - now <= 0
 *       OVERDUE  :  dueAt - now  < 0
 *     N8N/1.1 takes DUE and OVERDUE together as 'overdue' for escalation; the bucket label is
 *     preserved in the group key so the daily digest can show separate totals.
 */
/* organizationId is server-resolved (registry bound) for this run; the workflow
   never treats the body as authority. The supervisor lookup is a redacted-id map
   from $env.N8N_FIXTURE_SUPERVISOR_MAP (JSON object: assignedToRedacted -> supervisorRedacted).
   If the supervisor is missing for an owner, group falls through to FALLBACK (no misroute, AC #5). */
const __in = $input.first().json || {};
const items = (__in.items || (__in.data && __in.data.items)) || [];
const triggerLabel = ($node["Build envelope (listDueNextActions)"].json.triggerLabel || 'TICK_15M');
const orgId = ($node["Build envelope (listDueNextActions)"].json.envelope.organizationId) || 'unknown-org';
let supervisorMap = {};
try { supervisorMap = JSON.parse($env.N8N_FIXTURE_SUPERVISOR_MAP || '{}'); } catch (_e) { supervisorMap = {}; }
const now = Date.now();
const buckets = { DUE_SOON: [], DUE: [], OVERDUE: [] };
for (const it of items) {
  if (it.status !== 'OPEN') continue;
  if (it.snoozeMode === 'SNOOZED') continue;
  const dt = Date.parse(it.dueAt) - now;
  let bucket;
  if (dt <= 0) bucket = 'OVERDUE';
  else if (dt <= 60 * 60 * 1000) bucket = 'DUE_SOON';
  else continue; /* not due yet; skip */
  buckets[bucket].push(it);
}
/* Group by (organization, owner, supervisor, slaBucket) — recipient keys are redacted ids from the wire. */
const groups = {};
for (const bucketName of Object.keys(buckets)) {
  for (const it of buckets[bucketName]) {
    const supervisorKey = (supervisorMap[it.assignedToRedacted] || it.supervisorRedacted || 'NONE');
    const keyOrg = orgId;
    const keyOwner = it.assignedToRedacted || 'NONE';
    const key = [keyOrg, keyOwner, supervisorKey, bucketName].join('|');
    if (!groups[key]) {
      groups[key] = {
        organizationId: keyOrg,
        ownerRedacted: keyOwner,
        supervisorRedacted: supervisorKey,
        slaBucket: bucketName,
        itemIds: [],
        firstDueAt: it.dueAt
      };
    }
    groups[key].itemIds.push(it.nextActionId);
    if (Date.parse(it.dueAt) < Date.parse(groups[key].firstDueAt)) {
      groups[key].firstDueAt = it.dueAt;
    }
  }
}
return [
  {
    json: {
      triggerLabel: triggerLabel,
      correlationId: $node["Build envelope (listDueNextActions)"].json.envelope.correlationId,
      totalSeen: items.length,
      totalKept: Object.values(groups).reduce((acc, g) => acc + g.itemIds.length, 0),
      groups: Object.values(groups),
      noItems: items.length === 0
    }
  }
];

/*
 * Build ONE sendSyntheticReminder envelope per group.
 * Audience is SUPERVISOR if slaBucket === 'OVERDUE' AND a supervisor is present, else OWNER.
 * If neither owner nor supervisor is present, this group is routed to the FALLBACK review
 * branch (no notification, no misroute).
 *
 * idempotencyKey is stable per (groupKey, day, workflowRevision) so:
 *   - 15-min tick + daily digest converge to the same key (AC #15, no double notify).
 *   - gateway-side replay returns the cached APPLIED result (AC #6, idempotency).
 */
const group = $input.first().json;
const groups = group.groups || [];
const out = [];
const correlationId = group.correlationId;
const dayKey = (new Date()).toISOString().slice(0, 10).replace(/[-]/g, '');
for (const g of groups) {
  const escalate = g.slaBucket === 'OVERDUE' && g.supervisorRedacted && g.supervisorRedacted !== 'NONE';
  const audience = escalate ? 'SUPERVISOR' : 'OWNER';
  const recipient = escalate ? g.supervisorRedacted : g.ownerRedacted;
  if (!recipient || recipient === 'NONE') {
    out.push({ json: { kind: 'fallback', group: g, correlationId: correlationId, reason: 'no_owner_or_supervisor' } });
    continue;
  }
  const groupKey = [g.organizationId, audience, recipient, g.slaBucket].join('|');
  const idem = 'rem-' + dayKey + '-' + groupKey.replace(/[^A-Za-z0-9._:-]/g, '-').slice(0, 96);
  out.push({
    json: {
      kind: 'send',
      envelope: {
        schemaVersion: '1',
        commandId: ('cmd-' + idem + '-' + Math.random().toString(36).slice(2, 6)).slice(0, 64),
        commandName: 'sendSyntheticReminder',
        idempotencyKey: idem,
        correlationId: correlationId,
        organizationId: g.organizationId,
        source: { kind: 'HRP_UI', provider: 'HRP_UI', connectionId: null },
        actor: { kind: 'SERVICE', serviceId: $env.HRP_AUTOMATION_SERVICE_ID },
        automationSource: {
          kind: 'N8N_AUTOMATION',
          workflowId: ($workflow.id),
          workflowRevision: 2,
          n8nExecutionId: ($execution.id),
          workflowLabel: 'sla-reminder-crm'
        },
        operation: {
          op: 'sendSyntheticReminder',
          payload: {
            schemaVersion: '1',
            nextActionId: g.itemIds[0],
            audienceKind: audience,
            redactedRecipientId: recipient,
            channel: 'DASHBOARD_ONLY',
            reminderRevisionId: 'rev-' + dayKey + '-' + g.slaBucket
          }
        }
      },
      fallback: null,
      group: g
    }
  });
}
return out;

/*
 * Build acknowledgement batches. AC #11: correlationId and n8nExecutionId MUST match the original
 * listDueNextActions call exactly; outcome is the wire status we just received, mapped to a
 * redacted outcome enum (SENT / FAILED / SKIPPED). We never include the raw wire body or any PII.
 *
 * Note: sendSyntheticReminder failure is acknowledged as FAILED; the gateway records it but does
 * not retry (no infinite retry, AC #8). Mock adapter offline returns a frozen 503 envelope
 * (AC #10) and is acknowledged as SKIPPED so the daily digest can re-attempt the next day.
 */
const sends = $input.all();
const acks = [];
for (const item of sends) {
  const it = item.json || {};
  if (it.kind === 'fallback') {
    /* No notification was sent; record a SKIPPED ack so the dedupe key is bound. */
    acks.push({
      json: {
        envelope: {
          schemaVersion: '1',
          commandId: 'cmd-ack-skip-' + Math.random().toString(36).slice(2, 8),
          commandName: 'acknowledgeReminder',
          idempotencyKey: 'ack-skip-' + (it.group.organizationId || 'unknown') + '-' + Date.now().toString(36),
          correlationId: it.correlationId,
          organizationId: it.group.organizationId || $env.HRP_AUTOMATION_ORG_ID,
          source: { kind: 'HRP_UI', provider: 'HRP_UI', connectionId: null },
          actor: { kind: 'SERVICE', serviceId: $env.HRP_AUTOMATION_SERVICE_ID },
          automationSource: {
            kind: 'N8N_AUTOMATION',
            workflowId: ($workflow.id),
            workflowRevision: 2,
            n8nExecutionId: ($execution.id),
            workflowLabel: 'sla-reminder-crm'
          },
          operation: {
            op: 'acknowledgeReminder',
            payload: {
              schemaVersion: '1',
              nextActionId: 'batch-' + (it.group.organizationId || 'unknown') + '-' + it.group.slaBucket,
              notificationOutcome: 'SKIPPED',
              reminderRevisionId: 'rev-skip-' + Date.now().toString(36),
              channel: 'DASHBOARD_ONLY'
            }
          }
        }
      }
    });
    continue;
  }
  const sent = it.envelope || null;
  const wire = (item.json && item.json.wireStatus) || null;
  const outcome = wire === 'APPLIED' ? 'SENT' : (wire === 'SKIPPED' ? 'SKIPPED' : 'FAILED');
  if (!sent) {
    acks.push({ json: { envelope: { schemaVersion: '1', commandId: 'cmd-ack-skip-' + Math.random().toString(36).slice(2, 8), commandName: 'acknowledgeReminder', idempotencyKey: 'ack-skip-' + (it.group ? it.group.organizationId : 'unknown') + '-' + (it.group ? it.group.slaBucket : 'NONE'), correlationId: it.correlationId, organizationId: it.group ? it.group.organizationId : $env.HRP_AUTOMATION_ORG_ID, source: { kind: 'HRP_UI', provider: 'HRP_UI', connectionId: null }, actor: { kind: 'SERVICE', serviceId: $env.HRP_AUTOMATION_SERVICE_ID }, automationSource: { kind: 'N8N_AUTOMATION', workflowId: ($workflow.id), workflowRevision: 2, n8nExecutionId: ($execution.id), workflowLabel: 'sla-reminder-crm' }, operation: { op: 'acknowledgeReminder', payload: { schemaVersion: '1', nextActionId: 'batch-' + (it.group ? it.group.organizationId : 'unknown'), notificationOutcome: 'SKIPPED', reminderRevisionId: 'rev-skip', channel: 'DASHBOARD_ONLY' } } } } });
    continue;
  }
  acks.push({
    json: {
      envelope: {
        schemaVersion: '1',
        commandId: 'cmd-ack-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 6),
        commandName: 'acknowledgeReminder',
        idempotencyKey: 'ack-' + sent.idempotencyKey,
        correlationId: sent.correlationId,
        organizationId: sent.organizationId,
        source: { kind: 'HRP_UI', provider: 'HRP_UI', connectionId: null },
        actor: { kind: 'SERVICE', serviceId: $env.HRP_AUTOMATION_SERVICE_ID },
        automationSource: {
          kind: 'N8N_AUTOMATION',
          workflowId: ($workflow.id),
          workflowRevision: 2,
          n8nExecutionId: ($execution.id),
          workflowLabel: 'sla-reminder-crm'
        },
        operation: {
          op: 'acknowledgeReminder',
          payload: {
            schemaVersion: '1',
            nextActionId: sent.operation.payload.nextActionId,
            notificationOutcome: outcome,
            reminderRevisionId: sent.operation.payload.reminderRevisionId,
            channel: 'DASHBOARD_ONLY'
          }
        }
      }
    }
  });
}
return acks;
